INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','اكتشف الدليل الشامل لصيانة شريط الـ TPE بقطر 20 سم وبلفة 1000 متر. تعلم أسرار زيادة العمر الافتراضي لمنتجات الزراعة الحديثة عبر تقنيات الصيانة المهنية.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
