INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','دانستن دقیق هزینه لوله ریت 90 میلی‌متر کمک می‌کند تا بودجه آبیاری مزرعه را بهتر برنامه‌ریزی کنید. این راهنما شامل جزئیات فنی و قیمت‌هاست.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
