INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','دليل المزارعين العراقيين لتطبيق أنظمة الري بالتنقيط ونظام الخطوط وفق المناخ المحلي' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','دليل شامل للمزارعين العراقيين يشرح كيفية تكييف أنظمة الري بالتنقيط ونظام الخطوط (AFS) مع الظروف المناخية المحلية لتحسين إنتاجية المحاصيل وترشيد استهلاك المياه.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
