INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','كيف تختار المرشح الصحيح لري القطري والنوع الشريطي؟ دليلكامل للمزارع' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على كيفية اختيار المرشح المناسب لأنظمة ري القطري والشريطي بفعالية. دليلكامل يوضح معايير الاختيار الصحيحة للمزارع لضمان أداء نظام ري عالي والحد من انسداد الأنابيب. تعلم الفرق بين أنواع المرشحات المختلفة واختر المرشح المثالي لكل نظام ري.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
