INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على أفضل الاستراتيجيات العملية لزيادة كفاءة الري بالرش (دقة الري) في المزارع الكبيرة. دليل مفصل للمزارعين العراقيين لتحسين استخدام المياه والزيادة في المحاصيل.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
