INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Роҳнамои пурра барои кам кардани анҷӯм дар роҳи ангоршавӣ бо истифода аз системаи мондаран. Методҳои самаранок барои фармори деҳотӣ барои бепарвоии самаранок дар замини кӯҳистӣ ва шароити хушк. Тавзеҳи таҳқиқи техникӣ ва татбиқи асбоби навтоза барои дарё ошомидан ва хубиста баррасӣ.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
